-- Remaining translation workflows, moderation, writer correspondence and email tables.
CREATE TABLE IF NOT EXISTS translation_entry_states (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,translation_key VARCHAR(255) NOT NULL,locale VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(state IN ('untranslated','draft','translated','needs_review','approved')),source_hash CHAR(64),updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(translation_key,locale));
CREATE INDEX IF NOT EXISTS idx_translation_entry_locale ON translation_entry_states(locale,state);
CREATE TABLE IF NOT EXISTS translation_imports (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,file_name VARCHAR(255) NOT NULL,file_format VARCHAR(12) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'preview' CHECK(status IN ('preview','confirmed','failed')),total_rows INTEGER NOT NULL DEFAULT 0 CHECK(total_rows>=0),new_count INTEGER NOT NULL DEFAULT 0 CHECK(new_count>=0),updated_count INTEGER NOT NULL DEFAULT 0 CHECK(updated_count>=0),unknown_count INTEGER NOT NULL DEFAULT 0 CHECK(unknown_count>=0),error_count INTEGER NOT NULL DEFAULT 0 CHECK(error_count>=0),report_json TEXT,created_at TIMESTAMPTZ DEFAULT now(),confirmed_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_translation_import_user ON translation_imports(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_translation_import_status ON translation_imports(status,created_at);
CREATE TABLE IF NOT EXISTS translation_import_rows (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,import_id BIGINT NOT NULL REFERENCES translation_imports(id) ON DELETE CASCADE,row_number INTEGER NOT NULL CHECK(row_number>=0),translation_key VARCHAR(255),entity_type VARCHAR(40),entity_id BIGINT NOT NULL DEFAULT 0 CHECK(entity_id>=0),field_name VARCHAR(80),source_locale VARCHAR(20),source_text TEXT,source_hash CHAR(64),translations_json TEXT,action_name VARCHAR(30) NOT NULL DEFAULT 'skip',validation_state VARCHAR(12) NOT NULL DEFAULT 'valid' CHECK(validation_state IN ('valid','warning','error','unknown')),messages_json TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_translation_import_row ON translation_import_rows(import_id,row_number);
CREATE INDEX IF NOT EXISTS idx_translation_import_key ON translation_import_rows(translation_key);
CREATE TABLE IF NOT EXISTS community_moderation_terms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,phrase VARCHAR(255) NOT NULL,normalized_phrase VARCHAR(255) NOT NULL UNIQUE,exception_phrase VARCHAR(255),severity VARCHAR(10) NOT NULL DEFAULT 'review' CHECK(severity IN ('warning','review','block')),active BOOLEAN NOT NULL DEFAULT TRUE,notes VARCHAR(500),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_moderation_terms_active ON community_moderation_terms(active,severity);
CREATE TABLE IF NOT EXISTS community_moderation_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,content_type VARCHAR(10) NOT NULL CHECK(content_type IN ('topic','reply')),content_id BIGINT NOT NULL,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,severity VARCHAR(10) NOT NULL CHECK(severity IN ('warning','review','block')),status VARCHAR(12) NOT NULL DEFAULT 'open' CHECK(status IN ('open','approved','rejected','dismissed')),matched_terms TEXT,content_excerpt VARCHAR(1000),reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMP,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_moderation_event_status ON community_moderation_events(status,severity,created_at);
CREATE INDEX IF NOT EXISTS idx_moderation_event_content ON community_moderation_events(content_type,content_id);
CREATE INDEX IF NOT EXISTS idx_moderation_event_user ON community_moderation_events(user_id,created_at);
CREATE TABLE IF NOT EXISTS content_translation_assignments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,content_type VARCHAR(40) NOT NULL,content_id BIGINT NOT NULL,target_locale VARCHAR(20) NOT NULL,translator_id BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewer_id BIGINT REFERENCES users(id) ON DELETE SET NULL,assigned_by BIGINT REFERENCES users(id) ON DELETE SET NULL,status VARCHAR(15) NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','in_progress','review','approved','cancelled')),notes TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),UNIQUE(content_type,content_id,target_locale));
CREATE INDEX IF NOT EXISTS idx_translation_assign_content ON content_translation_assignments(content_type,content_id);
CREATE INDEX IF NOT EXISTS idx_translation_assign_translator ON content_translation_assignments(translator_id,status);
CREATE INDEX IF NOT EXISTS idx_translation_assign_reviewer ON content_translation_assignments(reviewer_id,status);
CREATE TABLE IF NOT EXISTS writer_application_messages (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES writer_applications(id) ON DELETE CASCADE,sender_id BIGINT REFERENCES users(id) ON DELETE SET NULL,visibility VARCHAR(12) NOT NULL DEFAULT 'applicant' CHECK(visibility IN ('applicant','internal')),body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_writer_app_message ON writer_application_messages(application_id,visibility,created_at);
CREATE INDEX IF NOT EXISTS idx_writer_app_message_sender ON writer_application_messages(sender_id);
CREATE TABLE IF NOT EXISTS email_notification_templates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_key VARCHAR(100) NOT NULL UNIQUE,subject VARCHAR(255) NOT NULL,body_html TEXT,body_text TEXT,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS email_delivery_attempts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_key VARCHAR(100) NOT NULL,recipient VARCHAR(255) NOT NULL,subject VARCHAR(255) NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','accepted','failed')),attempts INTEGER NOT NULL DEFAULT 0,error TEXT,related_type VARCHAR(80),related_id BIGINT,created_at TIMESTAMPTZ DEFAULT now(),sent_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_email_attempt_status ON email_delivery_attempts(event_key,status);
CREATE INDEX IF NOT EXISTS idx_email_attempt_related ON email_delivery_attempts(related_type,related_id);
CREATE TABLE IF NOT EXISTS writer_application_notes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL REFERENCES writer_applications(id) ON DELETE CASCADE,author_id BIGINT REFERENCES users(id) ON DELETE SET NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_writer_app_notes ON writer_application_notes(application_id,created_at);
CREATE TABLE IF NOT EXISTS story_submission_revisions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,submission_id BIGINT NOT NULL REFERENCES story_submissions(id) ON DELETE CASCADE,revision_no INTEGER NOT NULL CHECK(revision_no>=0),title VARCHAR(220) NOT NULL,name VARCHAR(160) NOT NULL,story TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_story_revision ON story_submission_revisions(submission_id,revision_no);
